class Solution {
  public long interactionCosts(int n, int[][] edges, int[] group) {
    int G = 21;
    int[] start = new int[n + 1];
    for (int[] e : edges) {
      start[e[0] + 1]++;
      start[e[1] + 1]++;
    }
    for (int i = 0; i < n; i++) start[i + 1] += start[i];
    int[] fill = new int[n], to = new int[2 * Math.max(0, n - 1)];
    for (int[] e : edges) {
      to[start[e[0]] + fill[e[0]]++] = e[1];
      to[start[e[1]] + fill[e[1]]++] = e[0];
    }
    int[] order = new int[n], par = new int[n];
    par[0] = -1;
    int head = 0, tail = 0;
    order[tail++] = 0;
    while (head < tail) {
      int u = order[head++];
      for (int p = start[u]; p < start[u + 1]; p++) {
        if (to[p] != par[u]) {
          par[to[p]] = u;
          order[tail++] = to[p];
        }
      }
    }
    long[] total = new long[G];
    for (int g : group) total[g]++;
    int[][] sub = new int[n][G];
    long ans = 0;
    for (int idx = n - 1; idx >= 0; idx--) {
      int u = order[idx];
      sub[u][group[u]]++;
      if (par[u] >= 0) {
        for (int g = 1; g < G; g++) {
          ans += (long) sub[u][g] * (total[g] - sub[u][g]);
          sub[par[u]][g] += sub[u][g];
        }
      }
    }
    return ans;
  }
}
